package com.forgeci.application.security;
import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class FieldEncryptionService {
 private final SecretKeySpec key; private final SecureRandom random=new SecureRandom();
 public FieldEncryptionService(@Value("${forgeci.security.encryption-key}") String encoded){byte[] b;try{b=Base64.getDecoder().decode(encoded);}catch(IllegalArgumentException e){throw new IllegalArgumentException("Encryption key must be base64");}if(b.length!=32)throw new IllegalArgumentException("Encryption key must decode to 32 bytes");key=new SecretKeySpec(b,"AES");}
 public String encrypt(String value){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] ciphertext=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] out=new byte[iv.length+ciphertext.length];System.arraycopy(iv,0,out,0,iv.length);System.arraycopy(ciphertext,0,out,iv.length,ciphertext.length);return Base64.getEncoder().encodeToString(out);}catch(Exception e){throw new IllegalStateException("Unable to encrypt credential",e);}}
 public String decrypt(String encoded){try{byte[] all=Base64.getDecoder().decode(encoded);byte[] iv=java.util.Arrays.copyOfRange(all,0,12);byte[] ct=java.util.Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(ct),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Unable to decrypt credential",e);}}
}
